{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "In humans, cilomilast has an absolute oral bioavailability close to 100%, demonstrating that a small lipophilic oral drug can be essentially completely absorbed with negligible first-pass loss.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Nevirapine absolute oral bioavailability was 91 ± 8% in healthy volunteers, supporting high F for a small lipophilic drug without ionizable acid or phenolic groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Ethosuximide, a small neutral lipophilic drug, has absolute oral bioavailability >90% in humans, closely matching the query's small non-polar amine-containing scaffold and supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Bicifadine, a lipophilic bridged bicyclic amine, has absolute oral bioavailability ~67% in humans, supporting high F for the query's adamantane amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Pentazocine has low absolute oral bioavailability (18%) in healthy subjects, but this is attributed to extensive first-pass glucuronidation of its phenolic hydroxyl, a metabolic liability absent in the adamantane primary amine query; therefore it does not support low F for the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Rasagiline has absolute oral bioavailability ~36% due to extensive CYP1A2-mediated first-pass metabolism of its propargylamine moiety; the query lacks this metabolic soft spot, so this low-F evidence is not mechanistically transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small lipophilic adamantane primary amine (memantine). High-F analogues with similar physicochemical features—cilomilast, nevirapine, ethosuximide, and bicifadine—show essentially complete or high oral bioavailability. Low-F analogues (pentazocine, rasagiline) have specific metabolic or polarity liabilities absent in the query. Thus high F (>=20%) is better supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule in the provided evidence set; prediction relies on transferable analogues and known pharmacology."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

